//SPDX-License-Identifier: MIT
pragma solidity ~0.8.17;

// A fork of ENS's ETHRegistrarController (ens-contracts 1.7.0,
// vendor/ens-contracts/contracts/ethregistrar/ETHRegistrarController.sol).
// Commit-reveal, pricing through the oracle, resolver setup and reverse
// records are ENS's code as it was. Every change is marked `ZNS:` and is one
// of these:
//
// - the TLD is .znn, not .eth;
// - a label is 3 to 63 characters of a-z, 0-9 and "-", checked here rather
//   than left to clients (see `valid`);
// - short names carry a launch premium: ENS's decaying premium, started at
//   launch instead of at an expiry (see `_rentPrice`);
// - the label is recorded in the registrar on every registration and
//   renewal, so the token can name itself (see ZNSRegistrar);
// - ENS's second reverse record, default.reverse, is left out: it is for a
//   name shared across many chains, and a .znn name lives on one;
// - rent is burned as it is paid, to the ZVM's burn address, instead of
//   collecting for the owner to withdraw (see `BURN`).

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ERC165} from "@openzeppelin/contracts/utils/introspection/ERC165.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";

import {StringUtils} from "@ensdomains/ens-contracts/contracts/utils/StringUtils.sol";
import {Resolver} from "@ensdomains/ens-contracts/contracts/resolvers/Resolver.sol";
import {ENS} from "@ensdomains/ens-contracts/contracts/registry/ENS.sol";
import {IReverseRegistrar} from "@ensdomains/ens-contracts/contracts/reverseRegistrar/IReverseRegistrar.sol";
import {IETHRegistrarController, IPriceOracle} from "@ensdomains/ens-contracts/contracts/ethregistrar/IETHRegistrarController.sol";
import {ERC20Recoverable} from "@ensdomains/ens-contracts/contracts/utils/ERC20Recoverable.sol";

import {ZNSRegistrar} from "./ZNSRegistrar.sol";

/// @dev A registrar controller for registering and renewing .znn names at
/// the oracle's price.
contract ZNSController is Ownable, IETHRegistrarController, ERC165, ERC20Recoverable {
    using StringUtils for *;

    /// @notice The bitmask for the reverse record (addr.reverse).
    uint8 constant REVERSE_RECORD_ETHEREUM_BIT = 1;

    /// @notice The minimum duration for a registration.
    uint256 public constant MIN_REGISTRATION_DURATION = 28 days;

    // ZNS: namehash("znn").
    bytes32 public constant ZNN_NODE = 0x6be5efe3a46d2356cb7ec1033d96cb4f426a49b9805d060359fade58800cf633;

    // ZNS: where rent goes. The ZVM's burn address, the one its fee split
    // already burns relayed tips to (zvm-docs spec/SPEC.md, "The relayed fee
    // split"), so the chain's own burn accounting counts ZNS's too. Rent is
    // sent there in the same transaction that pays it: the controller never
    // holds a balance, and there is nothing for an owner to withdraw.
    address payable public constant BURN = payable(0x000000000000000000000000000000000000dEaD);

    // ZNS: the registrar's grace period, repeated because ENS's oracle and
    // registrar each hard-code it too.
    uint256 constant GRACE_PERIOD = 90 days;

    /// @notice The ENS registry.
    ENS public immutable ens;

    // ZNS: typed as the .znn registrar, which records labels.
    ZNSRegistrar immutable base;

    /// @notice The minimum time a commitment must exist to be valid.
    uint256 public immutable minCommitmentAge;

    /// @notice The maximum time a commitment can exist to be valid.
    uint256 public immutable maxCommitmentAge;

    /// @notice The registrar for addr.reverse.
    IReverseRegistrar public immutable reverseRegistrar;

    /// @notice The price oracle for the znn TLD.
    IPriceOracle public immutable prices;

    // ZNS: when names first opened. A name that has never been registered and
    // is at most `launchMaxLength` characters is priced as if it had expired
    // out of its grace period at this moment, so it goes through the same
    // falling-price auction an expired name does.
    uint256 public immutable launchTime;
    uint256 public immutable launchMaxLength;

    /// @notice A mapping of commitments to their timestamp.
    mapping(bytes32 => uint256) public commitments;

    error CommitmentNotFound(bytes32 commitment);
    error CommitmentTooNew(bytes32 commitment, uint256 minimumCommitmentTimestamp, uint256 currentTimestamp);
    error CommitmentTooOld(bytes32 commitment, uint256 maximumCommitmentTimestamp, uint256 currentTimestamp);
    error NameNotAvailable(string name);
    error DurationTooShort(uint256 duration);
    error ResolverRequiredWhenDataSupplied();
    error ResolverRequiredForReverseRecord();
    error UnexpiredCommitmentExists(bytes32 commitment);
    error InsufficientValue();
    error MaxCommitmentAgeTooLow();
    error MaxCommitmentAgeTooHigh();
    // ZNS: a reverse-record bit this controller does not set.
    error UnsupportedReverseRecord(uint8 reverseRecord);

    event NameRegistered(
        string label,
        bytes32 indexed labelhash,
        address indexed owner,
        uint256 baseCost,
        uint256 premium,
        uint256 expires,
        bytes32 referrer
    );

    event NameRenewed(string label, bytes32 indexed labelhash, uint256 cost, uint256 expires, bytes32 referrer);

    constructor(
        ZNSRegistrar _base,
        IPriceOracle _prices,
        uint256 _minCommitmentAge,
        uint256 _maxCommitmentAge,
        IReverseRegistrar _reverseRegistrar,
        ENS _ens,
        uint256 _launchMaxLength
    ) {
        if (_maxCommitmentAge <= _minCommitmentAge) revert MaxCommitmentAgeTooLow();

        if (_maxCommitmentAge > block.timestamp) revert MaxCommitmentAgeTooHigh();

        ens = _ens;
        base = _base;
        prices = _prices;
        minCommitmentAge = _minCommitmentAge;
        maxCommitmentAge = _maxCommitmentAge;
        reverseRegistrar = _reverseRegistrar;
        launchTime = block.timestamp;
        launchMaxLength = _launchMaxLength;
    }

    function rentPrice(string calldata label, uint256 duration)
        public
        view
        override
        returns (IPriceOracle.Price memory price)
    {
        bytes32 labelhash = keccak256(bytes(label));
        price = _rentPrice(label, labelhash, duration);
    }

    /// @notice Returns true if the label may be registered.
    ///
    /// ZNS: ENS accepts any string of three or more characters and leaves
    /// normalisation (ENSIP-15) to clients. A name no client normalises to
    /// itself can be registered and never resolved, and a look-alike
    /// ("аlice" with a Cyrillic а) can be registered beside the real one.
    /// Checking here closes both: every name this accepts is already in
    /// normal form, so it resolves in viem, in the ZNS page and in any
    /// ENS-aware tool unchanged. The price is that there are no emoji or
    /// non-Latin names.
    ///
    /// The rule: 3 to 63 characters (DNS's label limit) of a-z, 0-9 and "-",
    /// not starting or ending with "-", and no "--" in the third and fourth
    /// places, which ENSIP-15 reserves.
    function valid(string calldata label) public pure returns (bool) {
        bytes memory b = bytes(label);
        if (b.length < 3 || b.length > 63) return false;
        if (b[0] == "-" || b[b.length - 1] == "-") return false;
        if (b.length >= 4 && b[2] == "-" && b[3] == "-") return false;
        for (uint256 i; i < b.length; i++) {
            bytes1 c = b[i];
            if (!((c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c == "-")) return false;
        }
        return true;
    }

    function available(string calldata label) public view override returns (bool) {
        bytes32 labelhash = keccak256(bytes(label));
        return _available(label, labelhash);
    }

    function makeCommitment(Registration calldata registration) public pure override returns (bytes32 commitment) {
        if (registration.data.length > 0 && registration.resolver == address(0)) {
            revert ResolverRequiredWhenDataSupplied();
        }

        if (registration.reverseRecord != 0 && registration.resolver == address(0)) {
            revert ResolverRequiredForReverseRecord();
        }

        // ZNS: only the addr.reverse bit exists here.
        if (registration.reverseRecord & ~REVERSE_RECORD_ETHEREUM_BIT != 0) {
            revert UnsupportedReverseRecord(registration.reverseRecord);
        }

        if (registration.duration < MIN_REGISTRATION_DURATION) revert DurationTooShort(registration.duration);

        return keccak256(abi.encode(registration));
    }

    function commit(bytes32 commitment) public override {
        if (commitments[commitment] + maxCommitmentAge >= block.timestamp) {
            revert UnexpiredCommitmentExists(commitment);
        }
        commitments[commitment] = block.timestamp;
    }

    function register(Registration calldata registration) public payable override {
        bytes32 labelhash = keccak256(bytes(registration.label));
        IPriceOracle.Price memory price = _rentPrice(registration.label, labelhash, registration.duration);
        uint256 totalPrice = price.base + price.premium;
        if (msg.value < totalPrice) revert InsufficientValue();

        if (!_available(registration.label, labelhash)) revert NameNotAvailable(registration.label);

        bytes32 commitment = makeCommitment(registration);
        uint256 commitmentTimestamp = commitments[commitment];

        // Require an old enough commitment.
        if (commitmentTimestamp + minCommitmentAge > block.timestamp) {
            revert CommitmentTooNew(commitment, commitmentTimestamp + minCommitmentAge, block.timestamp);
        }

        // If the commitment is too old, or the name is registered, stop
        if (commitmentTimestamp + maxCommitmentAge <= block.timestamp) {
            if (commitmentTimestamp == 0) revert CommitmentNotFound(commitment);
            revert CommitmentTooOld(commitment, commitmentTimestamp + maxCommitmentAge, block.timestamp);
        }

        delete (commitments[commitment]);

        uint256 expires;

        if (registration.resolver == address(0)) {
            expires = base.register(uint256(labelhash), registration.owner, registration.duration);
            // ZNS: the token names itself from here on.
            base.recordLabel(registration.label);
        } else {
            expires = base.register(uint256(labelhash), address(this), registration.duration);
            // ZNS: as above; before the transfer, so the token already has
            // its name when it reaches its owner.
            base.recordLabel(registration.label);

            bytes32 namehash = keccak256(abi.encodePacked(ZNN_NODE, labelhash));
            ens.setRecord(namehash, registration.owner, registration.resolver, 0);
            if (registration.data.length > 0) {
                Resolver(registration.resolver).multicallWithNodeCheck(namehash, registration.data);
            }

            base.transferFrom(address(this), registration.owner, uint256(labelhash));

            if (registration.reverseRecord & REVERSE_RECORD_ETHEREUM_BIT != 0) {
                reverseRegistrar.setNameForAddr(
                    msg.sender, msg.sender, registration.resolver, string.concat(registration.label, ".znn")
                );
            }
        }

        emit NameRegistered(
            registration.label, labelhash, registration.owner, price.base, price.premium, expires, registration.referrer
        );

        // ZNS: burned, not held.
        BURN.transfer(totalPrice);
        if (msg.value > totalPrice) payable(msg.sender).transfer(msg.value - totalPrice);
    }

    function renew(string calldata label, uint256 duration, bytes32 referrer) external payable override {
        bytes32 labelhash = keccak256(bytes(label));

        IPriceOracle.Price memory price = _rentPrice(label, labelhash, duration);
        if (msg.value < price.base) revert InsufficientValue();

        uint256 expires = base.renew(uint256(labelhash), duration);
        // ZNS: the card shows the expiry, so its metadata changed.
        base.recordLabel(label);

        emit NameRenewed(label, labelhash, price.base, expires, referrer);

        // ZNS: burned, not held.
        BURN.transfer(price.base);
        if (msg.value > price.base) payable(msg.sender).transfer(msg.value - price.base);
    }

    /// @notice Burns anything the contract holds. ZNS: ENS's `withdraw` sent
    /// the balance to the owner; rent is burned as it is paid here, so the
    /// only balance there can be is ZNN forced in some other way, and it goes
    /// the same way.
    function withdraw() public {
        BURN.transfer(address(this).balance);
    }

    function supportsInterface(bytes4 interfaceID) public view override returns (bool) {
        return interfaceID == type(IETHRegistrarController).interfaceId || super.supportsInterface(interfaceID);
    }

    /* Internal functions */

    function _rentPrice(string calldata label, bytes32 labelhash, uint256 duration)
        internal
        view
        returns (IPriceOracle.Price memory price)
    {
        uint256 expires = base.nameExpires(uint256(labelhash));
        // ZNS: the launch premium. ENS's oracle starts its premium when a
        // name leaves its grace period, `expires + 90 days`; a name that was
        // never registered has expires 0 and so no premium at all. Pricing a
        // never-registered short name as if it had expired at launch starts
        // the same auction for it on launch day, and lets it fall to the base
        // rent over the oracle's schedule.
        if (expires == 0 && label.strlen() <= launchMaxLength) {
            expires = launchTime - GRACE_PERIOD;
        }
        price = prices.price(label, expires, duration);
    }

    function _available(string calldata label, bytes32 labelhash) internal view returns (bool) {
        return valid(label) && base.available(uint256(labelhash));
    }
}

src/ZNSPriceFeed.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ~0.8.17;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {AggregatorInterface} from "@ensdomains/ens-contracts/contracts/ethregistrar/StablePriceOracle.sol";

/// @title ZNSPriceFeed
/// @notice The rate ENS's StablePriceOracle converts rent with, set by an
/// owner instead of read from Chainlink.
///
/// StablePriceOracle prices a name in "attoUSD" and converts to the chain's
/// coin with `amount * 1e8 / latestAnswer()`, the shape of Chainlink's
/// 8-decimal ETH/USD feed. The ZVM has no such feed, so this answers in its
/// place. At the deployed answer of 1e8 the oracle's unit *is* the ZNN wei:
/// the rent table reads directly in ZNN. Moving the answer rescales every
/// tier and the premium together; halving it doubles every price. Changing
/// the ratio between tiers needs a new oracle and a new controller, because
/// both hold their oracle as an immutable.
///
/// ENS ships a DummyOracle of this shape for tests, whose `set` anyone may
/// call. This one answers to an owner, and says so in an event, so a price
/// change is on the record.
contract ZNSPriceFeed is Ownable, AggregatorInterface {
    int256 public override latestAnswer;

    /// Chainlink's event for a new answer, so tooling that watches feeds reads
    /// this one too.
    event AnswerUpdated(int256 indexed current, uint256 indexed roundId, uint256 updatedAt);

    error AnswerNotPositive();

    constructor(int256 answer) {
        set(answer);
    }

    function set(int256 answer) public onlyOwner {
        // Zero would divide by zero inside the oracle, and a negative answer
        // would cast to an enormous uint: either one makes every name
        // unregistrable.
        if (answer <= 0) revert AnswerNotPositive();
        latestAnswer = answer;
        emit AnswerUpdated(answer, 0, block.timestamp);
    }
}

src/ZNSRegistrar.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ~0.8.17;

import {BaseRegistrarImplementation} from "@ensdomains/ens-contracts/contracts/ethregistrar/BaseRegistrarImplementation.sol";
import {ENS} from "@ensdomains/ens-contracts/contracts/registry/ENS.sol";
import {Base64} from "@openzeppelin/contracts/utils/Base64.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";

/// @title ZNSRegistrar
/// @notice The .znn registrar: ENS's BaseRegistrarImplementation, unchanged
/// underneath, with three things added that a name needs on a chain with no
/// ENS subgraph and no ENS metadata service.
///
/// 1. **The label, in plain text.** ENS keeps only `keccak256(label)`, and
///    reads names back from a subgraph that indexes the controller's events.
///    Here the label is stored beside the token, so `tokenURI` can say
///    "alice.znn" and a marketplace that indexes nothing but ERC-721 events
///    (Karum, through the node's index) shows a name rather than a hash.
///    Recording is permissionless and proves itself: the label must hash to
///    a token that exists, so nobody can record a wrong one.
///
/// 2. **The art and metadata, on chain.** `tokenURI` is a data: URI, built
///    here, so a name looks the same in every wallet and market and nothing
///    has to be hosted for it. ERC-4906's MetadataUpdate is emitted whenever a
///    name's expiry moves, which is the one thing on its card that changes.
///
/// 3. **Selling a name hands over control of it.** In ENS the NFT (the
///    registrant) and the registry node (the controller) are separate: a buyer
///    who receives the token still has to call `reclaim` before they can set a
///    single record, and until then the seller can. Every transfer here also
///    moves the registry node to the new holder, which is what the NameWrapper
///    does for wrapped names. The records themselves (where the name points)
///    are not touched: the buyer's first job is to point it at themselves.
contract ZNSRegistrar is BaseRegistrarImplementation {
    using Strings for uint256;

    /// keccak256(label) => label, for every name registered through a
    /// controller that records it.
    mapping(uint256 => string) public labelOf;

    /// Where a name's page lives, for `external_url`; the label and ".znn"
    /// are appended after "#/name/".
    string public siteURL;

    event LabelRecorded(uint256 indexed id, string label);
    /// ERC-4906.
    event MetadataUpdate(uint256 _tokenId);
    event BatchMetadataUpdate(uint256 _fromTokenId, uint256 _toTokenId);
    /// ERC-7572, which the node's NFT index listens for.
    event ContractURIUpdated();

    error UnknownName(string label);

    constructor(ENS _ens, bytes32 _baseNode, string memory _siteURL) BaseRegistrarImplementation(_ens, _baseNode) {
        siteURL = _siteURL;
    }

    function name() public pure override returns (string memory) {
        return "ZNS";
    }

    function symbol() public pure override returns (string memory) {
        return "ZNS";
    }

    /// @notice Records a name's label, and tells indexers its metadata may have
    /// changed. The controller calls this on every registration and renewal;
    /// anyone else may, for a name registered some other way.
    function recordLabel(string calldata label) external {
        uint256 id = uint256(keccak256(bytes(label)));
        if (!_exists(id)) revert UnknownName(label);
        if (bytes(labelOf[id]).length == 0) {
            labelOf[id] = label;
            emit LabelRecorded(id, label);
        }
        emit MetadataUpdate(id);
    }

    function setSiteURL(string calldata url) external onlyOwner {
        siteURL = url;
        emit ContractURIUpdated();
        emit BatchMetadataUpdate(0, type(uint256).max);
    }

    /// Keeps the registry node with the token: see the contract's note (3).
    /// Mints and burns are left alone, because `_register` sets the node
    /// itself, and a node the registrar no longer controls (the registrar was
    /// retired) is left alone rather than blocking the transfer.
    function _afterTokenTransfer(address from, address to, uint256 firstTokenId, uint256 batchSize)
        internal
        override
    {
        super._afterTokenTransfer(from, to, firstTokenId, batchSize);
        if (from != address(0) && to != address(0) && ens.owner(baseNode) == address(this)) {
            ens.setSubnodeOwner(baseNode, bytes32(firstTokenId), to);
        }
    }

    // --- metadata -----------------------------------------------------------

    function tokenURI(uint256 id) public view override returns (string memory) {
        _requireMinted(id);
        string memory label = labelOf[id];
        // ENS's own spelling for a label nobody has recorded: its hash in
        // brackets.
        bool known = bytes(label).length != 0;
        string memory full = known
            ? string.concat(label, ".znn")
            : string.concat("[", uint256(id).toHexString(32), "].znn");
        uint256 len = known ? bytes(label).length : 0;
        uint256 expires = expiries[id];

        // In pieces: one string.concat of all of it is too many stack slots
        // for the legacy code generator.
        string memory head = string.concat(
            '{"name":"',
            full,
            '","description":"',
            full,
            ', a name on the ZVM. Whoever holds this token controls where the name points. It must be renewed before it expires, or it returns to the pool after a 90-day grace period.","image":"data:image/svg+xml;base64,',
            Base64.encode(bytes(_art(known ? label : "?", len, expires)))
        );
        string memory tail = string.concat(
            '","external_url":"', siteURL, "#/name/", full, '","attributes":[', _attributes(label, len, expires), "]}"
        );
        return string.concat("data:application/json;base64,", Base64.encode(bytes(string.concat(head, tail))));
    }

    /// The collection's own card, which the node's index reads for Karum.
    function contractURI() external view returns (string memory) {
        string memory json = string.concat(
            '{"name":"ZNS","description":"Names on the ZVM. A .znn name points at an address, and an address can name itself back. Names are rented by the year: short ones cost more, and an expired name returns to the pool through a falling-price auction.","image":"data:image/svg+xml;base64,',
            Base64.encode(bytes(_logo())),
            '","external_link":"',
            siteURL,
            '"}'
        );
        return string.concat("data:application/json;base64,", Base64.encode(bytes(json)));
    }

    // supportsInterface stays ENS's, which does not claim ERC-721 metadata
    // (0x5b5e139f): the base contract's is not virtual, so it cannot be
    // extended here. The node's index calls tokenURI without asking first.

    function _attributes(string memory label, uint256 len, uint256 expires) internal pure returns (string memory) {
        return string.concat(
            '{"trait_type":"Length","display_type":"number","value":',
            len.toString(),
            '},{"trait_type":"Characters","value":"',
            _charset(label),
            '"},{"trait_type":"Expires","display_type":"date","value":',
            expires.toString(),
            "}"
        );
    }

    function _charset(string memory label) internal pure returns (string memory) {
        bytes memory b = bytes(label);
        bool letters;
        bool digits;
        bool other;
        for (uint256 i; i < b.length; i++) {
            bytes1 c = b[i];
            if (c >= "a" && c <= "z") letters = true;
            else if (c >= "0" && c <= "9") digits = true;
            else other = true;
        }
        if (b.length == 0) return "Unknown";
        if (other || (letters && digits)) return "Mixed";
        return letters ? "Letters" : "Digits";
    }

    /// The tier colour: Zenon's pink for three characters, NoM blue for four,
    /// ZVM green for five and up, so a short name reads as one across a grid.
    function _tint(uint256 len) internal pure returns (string memory) {
        if (len == 0) return "#7b9094";
        if (len <= 3) return "#f91690";
        if (len == 4) return "#5da4ff";
        return "#00d557";
    }

    // The label is only ever [a-z0-9-] (the controller refuses anything else),
    // or "?", so it is written into the SVG without escaping.
    function _art(string memory label, uint256 len, uint256 expires) internal pure returns (string memory) {
        string memory tint = _tint(len);
        // Sized so the whole name fits the card's 432 units at about 0.6em a
        // character, between 14 and 92.
        uint256 size = 720 / ((len == 0 ? 64 : len) + 4);
        if (size > 92) size = 92;
        if (size < 14) size = 14;
        string memory backdrop = string.concat(
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><defs><radialGradient id="g" cx=".15" cy=".1" r="1.15"><stop offset="0" stop-color="',
            tint,
            '" stop-opacity=".5"/><stop offset=".5" stop-color="',
            tint,
            '" stop-opacity=".07"/><stop offset="1" stop-color="#06090a" stop-opacity="0"/></radialGradient><pattern id="p" width="32" height="32" patternUnits="userSpaceOnUse"><path d="M32 0H0V32" fill="none" stroke="#fff" stroke-opacity=".05"/></pattern></defs><rect width="512" height="512" fill="#06090a"/><rect width="512" height="512" fill="url(#p)"/><rect width="512" height="512" fill="url(#g)"/>',
            _mark(tint)
        );
        string memory title = string.concat(
            '<g font-family="Space Grotesk,ui-sans-serif,system-ui,Segoe UI,sans-serif"><text x="78" y="66" font-size="20" font-weight="600" letter-spacing="2" fill="#e6efec">ZNS</text><text x="40" y="292" font-size="',
            size.toString(),
            '" font-weight="700" letter-spacing="-1" fill="#e6efec">',
            label,
            '<tspan fill="',
            tint,
            '">.znn</tspan></text></g>'
        );
        return string.concat(
            backdrop,
            title,
            '<text x="40" y="470" font-family="ui-monospace,Consolas,monospace" font-size="15" letter-spacing="1.5" fill="#7b9094">EXPIRES ',
            _date(expires),
            "</text></svg>"
        );
    }

    function _mark(string memory tint) internal pure returns (string memory) {
        return string.concat(
            '<path d="M40 44h26L40 72h26" fill="none" stroke="',
            tint,
            '" stroke-width="5" stroke-linecap="square" stroke-linejoin="miter"/>'
        );
    }

    function _logo() internal pure returns (string memory) {
        return string.concat(
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><rect width="512" height="512" fill="#06090a"/><circle cx="256" cy="256" r="200" fill="#00d557" fill-opacity=".08"/><path d="M156 150h200L156 362h200" fill="none" stroke="#00d557" stroke-width="40" stroke-linecap="square" stroke-linejoin="miter"/><path d="M228 256h56" stroke="#f91690" stroke-width="40"/></svg>'
        );
    }

    /// A Unix time as YYYY-MM-DD in UTC (Howard Hinnant's civil_from_days).
    function _date(uint256 t) internal pure returns (string memory) {
        int256 z = int256(t / 1 days) + 719468;
        int256 era = z / 146097;
        int256 doe = z - era * 146097;
        int256 yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
        int256 doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
        int256 mp = (5 * doy + 2) / 153;
        int256 d = doy - (153 * mp + 2) / 5 + 1;
        int256 m = mp < 10 ? mp + 3 : mp - 9;
        int256 y = yoe + era * 400 + (m <= 2 ? int256(1) : int256(0));
        return string.concat(uint256(y).toString(), "-", _two(uint256(m)), "-", _two(uint256(d)));
    }

    function _two(uint256 v) internal pure returns (string memory) {
        return v < 10 ? string.concat("0", v.toString()) : v.toString();
    }
}
